```typescript
export interface DeckOption {
  value: string;
  label: string;
  idleGlyph?: string;
  chosenGlyph?: string;
  fill?: string;
  disabled?: boolean;
}

export interface DeckSnapshot {
  options: DeckOption[];
  selected: string | undefined;
  direction: "ltr" | "rtl";
}

export class ChoiceDeck {
  private readonly options: DeckOption[];
  private selected: string | undefined;
  private readonly rtl: boolean;
  private readonly listener: ((value: string) => void) | undefined;

  constructor(
    options: readonly DeckOption[],
    initial?: string,
    rtl = false,
    listener?: (value: string) => void
  ) {
    if (options.length === 0) throw new Error("options cannot be empty");
    const values = new Set<string>();
    this.options = options.map((option) => {
      if (option.value.trim().length === 0 || option.label.trim().length === 0) {
        throw new Error("value and label must be non-blank");
      }
      if (values.has(option.value)) throw new Error("duplicate value");
      values.add(option.value);
      return { ...option };
    });
    if (initial !== undefined) {
      const option = this.options.find((candidate) => candidate.value === initial);
      if (option === undefined || option.disabled === true) {
        throw new Error("invalid initial value");
      }
    }
    this.selected = initial;
    this.rtl = rtl;
    this.listener = listener;
  }

  choose(value: string): boolean {
    const option = this.options.find((candidate) => candidate.value === value);
    if (option === undefined || value === this.selected) return false;
    this.selected = value;
    this.listener?.(value);
    return true;
  }

  snapshot(): DeckSnapshot {
    return {
      options: this.options.map((option) => ({ ...option })),
      selected: this.selected,
      direction: this.rtl ? "rtl" : "ltr"
    };
  }
}
```

