import { ChoiceDeck, DeckOption } from "./solution";

function assert(condition: boolean, message: string): void {
  if (!condition) throw new Error(message);
}
function equal<T>(actual: T, expected: T, message: string): void {
  if (!Object.is(actual, expected)) throw new Error(`${message}: expected ${String(expected)}, got ${String(actual)}`);
}
function throws(fn: () => unknown, message: string): void {
  let didThrow = false;
  try { fn(); } catch (error) { didThrow = error instanceof Error; }
  assert(didThrow, message);
}

throws(() => new ChoiceDeck([]), "empty option list is rejected");
throws(() => new ChoiceDeck([{ value: " ", label: "label" }]), "blank value is rejected");
throws(() => new ChoiceDeck([{ value: "value", label: "\t\n" }]), "blank label is rejected");
throws(() => new ChoiceDeck([{ value: "x", label: "one" }, { value: "x", label: "two" }]), "duplicate values are rejected");
throws(() => new ChoiceDeck([{ value: "x", label: "X" }], "missing"), "unknown initial value is rejected");
throws(() => new ChoiceDeck([{ value: "x", label: "X", disabled: true }], "x"), "disabled initial value is rejected");

const source: DeckOption[] = [
  { value: "one", label: "One", idleGlyph: "1", fill: "blue" },
  { value: "two", label: "Two", chosenGlyph: "2", disabled: true },
  { value: " three ", label: " Three " }
];
const notifications: string[] = [];
const deck = new ChoiceDeck(source, "one", true, value => notifications.push(value));
source[0].label = "Mutated";
source[0].disabled = true;
source.push({ value: "four", label: "Four" });
let snapshot = deck.snapshot();
equal(snapshot.options.length, 3, "constructor snapshots option collection");
equal(snapshot.options[0].label, "One", "constructor copies option objects");
equal(snapshot.selected, "one", "initial selection is retained");
equal(snapshot.direction, "rtl", "requested RTL direction is reported");

equal(deck.choose("unknown"), false, "unknown choice fails");
equal(deck.choose("two"), false, "disabled choice fails");
equal(deck.choose("one"), false, "already selected choice fails");
equal(notifications.length, 0, "failed choices do not notify");
equal(deck.snapshot().selected, "one", "failed choices retain selection");
equal(deck.choose(" three "), true, "enabled distinct choice succeeds");
equal(deck.snapshot().selected, " three ", "successful choice updates before return");
equal(notifications.join("|"), " three ", "successful choice notifies exactly once");

snapshot.options[0].label = "Changed snapshot";
snapshot.options.reverse();
snapshot = deck.snapshot();
equal(snapshot.options.map(option => option.value).join("|"), "one|two| three ", "snapshot returns fresh options in original order");
equal(snapshot.options[0].label, "One", "snapshot option objects are fresh");
equal(new ChoiceDeck([{ value: "x", label: "X" }]).snapshot().direction, "ltr", "direction defaults to LTR");

const listenerFailure = new Error("listener failure");
const failing = new ChoiceDeck(
  [{ value: "a", label: "A" }, { value: "b", label: "B" }],
  "a",
  false,
  () => { throw listenerFailure; }
);
let propagated: unknown;
try { failing.choose("b"); } catch (error) { propagated = error; }
equal(propagated, listenerFailure, "listener exception propagates");
equal(failing.snapshot().selected, "b", "selection is retained after listener exception");

